#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> f(n);
    for (int &x : f) cin >> x;

    vector<vector<int>> graph(n), reverseGraph(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        reverseGraph[b].push_back(a);
    }

    vector<char> reachableFromAssignment(n, false);
    queue<int> q;

    for (int i = 0; i < n; ++i) {
        if (f[i] == 1) {
            reachableFromAssignment[i] = true;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (int to : graph[v]) {
            if (f[to] != 1 && !reachableFromAssignment[to]) {
                reachableFromAssignment[to] = true;
                q.push(to);
            }
        }
    }

    vector<char> canReachUse(n, false);

    for (int i = 0; i < n; ++i) {
        if (f[i] == 2) {
            canReachUse[i] = true;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (int from : reverseGraph[v]) {
            if (!canReachUse[from]) {
                canReachUse[from] = true;
                if (f[from] != 1) {
                    q.push(from);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << (reachableFromAssignment[i] && canReachUse[i]) << '\n';
    }

    return 0;
}

